public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    /**
     * Credit_Review field set name. Fields are read at runtime so admins can add
     * or remove fields from the set without a code change.
     */
    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';

    /**
     * Field-set fields are added explicitly in getSObjectFieldList(), so the
     * fflib field-set option is off. CRUD/FLS checks are enabled as well.
     */
    public AccountsSelector() {
        super(false, true, true);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fieldList = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Set<String> seen = new Set<String>{
            Account.Id.getDescribe().getName().toLowerCase(),
            Account.Name.getDescribe().getName().toLowerCase(),
            Account.Industry.getDescribe().getName().toLowerCase()
        };

        Schema.FieldSet creditReviewFieldSet = Schema.SObjectType.Account.fieldSets.getMap()
            .get(CREDIT_REVIEW_FIELD_SET);

        if (creditReviewFieldSet != null) {
            Map<String, Schema.SObjectField> accountFieldMap = Schema.SObjectType.Account.fields.getMap();
            for (Schema.FieldSetMember member : creditReviewFieldSet.getFields()) {
                String fieldPath = member.getFieldPath().toLowerCase();
                if (seen.contains(fieldPath)) {
                    continue;
                }
                Schema.SObjectField sObjectField = accountFieldMap.get(fieldPath);
                if (sObjectField != null) {
                    seen.add(fieldPath);
                    fieldList.add(sObjectField);
                }
            }
        }

        return fieldList;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        fflib_QueryFactory accountQuery = newQueryFactory();
        accountQuery.setCondition('Id IN :accountIds');

        return (List<Account>) Database.query(withUserMode(accountQuery.toSOQL()));
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        fflib_QueryFactory accountQuery = newQueryFactory();
        accountQuery.setCondition('Id IN :accountIds');

        // Contact subquery built from ContactsSelector so it uses that selector's fields.
        new ContactsSelector().addQueryFactorySubselect(accountQuery, true);

        return (List<Account>) Database.query(withUserMode(accountQuery.toSOQL()));
    }

    /**
     * Inserts WITH USER_MODE into the generated SOQL. The clause must come after
     * the WHERE clause and before any top-level ORDER BY. Subquery ORDER BY clauses
     * sit inside parentheses, so only an ORDER BY after the last ')' is top-level.
     */
    private static String withUserMode(String soql) {
        Integer orderIdx = soql.lastIndexOf(' ORDER BY ');
        Integer lastCloseParen = soql.lastIndexOf(')');
        if (orderIdx >= 0 && orderIdx > lastCloseParen) {
            return soql.substring(0, orderIdx) + ' WITH USER_MODE' + soql.substring(orderIdx);
        }
        return soql + ' WITH USER_MODE';
    }
}
