```apex
/**
 * Trigger action for Contact, registered through Trigger_Action__mdt records.
 *
 * Rule: two Contacts on the same Account may not share an email address
 * (compared case-insensitively). Contacts without an AccountId or Email are not checked.
 *
 * - Insert: every Contact with an Account and an Email is checked.
 * - Update: only Contacts whose Email or AccountId changed are checked, so legacy
 *   duplicates do not block unrelated edits. A Contact never conflicts with itself.
 * - Within one save, the first Contact in the list that holds an (Account, Email) key
 *   is accepted and every later Contact with the same key is rejected.
 * - Rejections use addError on the individual record, so valid records in the same
 *   save still succeed (partial save).
 * - One SOQL query per execution, for up to 200 records.
 *
 * Without sharing is deliberate: the uniqueness rule applies to every Contact in the org,
 * so the check must see Contacts the running user cannot access.
 */
public without sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String DUPLICATE_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private static void validate(List<Contact> newContacts, List<Contact> oldContacts) {
        if (newContacts == null || newContacts.isEmpty()) {
            return;
        }

        Boolean isUpdate = oldContacts != null;

        // Determine which records are checked in this execution.
        List<Boolean> checked = new List<Boolean>();
        Set<Id> saveIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            if (c.Id != null) {
                saveIds.add(c.Id);
            }
            Boolean needsCheck = isCandidate(c)
                && (!isUpdate || isChanged(c, oldContacts[i]));
            checked.add(needsCheck);
            if (needsCheck) {
                accountIds.add(c.AccountId);
                emails.add(c.Email.toLowerCase());
            }
        }

        // Single query. Contacts in this save are excluded because their stored values
        // are stale; they are evaluated using their new values below.
        Set<String> taken = new Set<String>();
        if (!accountIds.isEmpty()) {
            for (Contact existing : [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
                  AND Id NOT IN :saveIds
            ]) {
                taken.add(buildKey(existing.AccountId, existing.Email));
            }
        }

        // Contacts in this save that are not being checked (unchanged on update) keep
        // their current values, so a changed Contact must not take their key.
        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            if (isCandidate(c) && !checked[i]) {
                taken.add(buildKey(c.AccountId, c.Email));
            }
        }

        // Checked Contacts in list order: first holder wins, later holders are rejected.
        for (Integer i = 0; i < newContacts.size(); i++) {
            if (!checked[i]) {
                continue;
            }
            Contact c = newContacts[i];
            String key = buildKey(c.AccountId, c.Email);
            if (taken.contains(key)) {
                c.addError(DUPLICATE_MESSAGE);
            } else {
                taken.add(key);
            }
        }
    }

    private static Boolean isCandidate(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private static Boolean isChanged(Contact newContact, Contact oldContact) {
        return newContact.Email != oldContact.Email
            || newContact.AccountId != oldContact.AccountId;
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
