public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    /*
     * Opportunity Ids already audited in this transaction. Static because TAF creates a new
     * action instance per trigger execution, and TA_Opportunity_RoundAmount re-updates the same
     * opportunities, which re-fires this trigger. This guarantees at most one 'Amount changed'
     * task per opportunity per transaction.
     */
    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>();
        for (SObject oldRecord : triggerOld) {
            oldById.put(oldRecord.Id, oldRecord);
        }

        List<Task> auditTasks = new List<Task>();
        for (SObject newRecord : triggerNew) {
            Opportunity newOpp = (Opportunity) newRecord;
            Opportunity oldOpp = (Opportunity) oldById.get(newOpp.Id);
            if (oldOpp == null || newOpp.Amount == oldOpp.Amount) {
                continue;
            }
            // Already audited in this transaction (for example, the re-entrant pass caused by rounding).
            if (!auditedOpportunityIds.add(newOpp.Id)) {
                continue;
            }
            auditTasks.add(new Task(
                Subject = 'Amount changed',
                WhatId = newOpp.Id,
                Status = 'Completed'
            ));
        }

        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }
}
