public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact c : (List<Contact>) triggerNew) {
            if (c.AccountId == null || !accountsById.containsKey(c.AccountId)) {
                continue;
            }

            // Only inherit when the contact has no mailing address of its own.
            if (String.isNotBlank(c.MailingStreet)
                || String.isNotBlank(c.MailingCity)
                || String.isNotBlank(c.MailingPostalCode)
                || String.isNotBlank(c.MailingCountry)) {
                continue;
            }

            Account parentAccount = accountsById.get(c.AccountId);
            c.MailingStreet = parentAccount.BillingStreet;
            c.MailingCity = parentAccount.BillingCity;
            c.MailingPostalCode = parentAccount.BillingPostalCode;
            c.MailingCountry = parentAccount.BillingCountry;
        }
    }
}
